const e=[{id:"sv-5-1226",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"The process owner tells the team to **recalculate the control limits on the first day of every month** 'to keep the charts fresh'. No signal or process change has occurred. Was this an appropriate instruction?",options:["Yes, because limits should always reflect the most recent month","Yes, because the control plan is a living document","No, because control limits can never be changed once set","No, because new limits should be based on signals that process performance has changed"],answer:3,hint:"Book p. 569: 'Establishing new limits'.",steps:[{title:"Key idea",body:"Book p. 569: establish new limits **based on signals that process performance has changed**."},{title:"Decide",body:"Monthly recalculation without a signal lets limits drift with the process and hides real shifts."}],final:"No — change limits only on signals → answer **D**",whyWrong:["Incorrect — recalculating by calendar lets a slow drift absorb itself into the limits.","Incorrect — 'living document' means updating as controls change, not resetting limits by habit.","Incorrect — limits CAN be changed, but only when signals show performance has changed.",""],bookRef:"Book p. 569"},{id:"sv-5-1227",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A new double-check on contract start dates has cut billing disputes. Six months later an auditor finds the check is **not mentioned in the billing SOP or the process map**; only the original team knows it. Which Control checklist concern does this show?",options:["The project has no Champion","The measurement system has not been analysed","The process is not capable","The change has not been referenced in the process procedures, so it is not standardised"],answer:3,hint:"Step Three: standardisation.",steps:[{title:"Key idea",body:"Book p. 578, Step Three: how is this referenced in process procedures and product drawings? what stops it being reinvented?"},{title:"Apply",body:"A check known only by the team will disappear when people move on; it must be written into the SOP and map."}],final:"Not standardised in procedures → answer **D**",whyWrong:["Incorrect — nothing suggests a missing Champion; the gap is in the documents.","Incorrect — MSA is a Measure-phase concern, not what the auditor found.","Incorrect — capability is not the issue; the control is undocumented.",""],bookRef:"Book pp. 567, 578"},{id:"sv-5-1228",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:1,stem:"Which item is NOT listed in the book's documentation plan?",options:["Updated process maps and flowcharts","The project charter","The FMEA","Training manuals"],answer:1,hint:"Book p. 567: process documentation and control plan documentation.",steps:[{title:"Key idea",body:"Book p. 567: process documentation (process maps, SOPs, FMEA) and control plan documentation (training manuals, monitoring plan, response plan, systems and structures)."},{title:"Find the outsider",body:"The charter is a Define document and not on the list."}],final:"Charter is not in the documentation plan → answer **B**",whyWrong:["Incorrect — updated process maps are listed under process documentation.","","Incorrect — the FMEA is listed under process documentation and as the response plan.","Incorrect — training manuals are listed under control plan documentation."],bookRef:"Book p. 567"},{id:"sv-5-1229",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"According to the book, what does the documentation plan often serve as in some organisations?",options:["The project charter for the next project","The actual final report of the project","The capital expenditure request","The baseline data collection plan"],answer:1,hint:"Look at the last line of the book's Documentation Plan slide.",steps:[{title:"Key idea",body:"Book p. 566: 'This is often the actual **Final Report** some organizations use.'"},{title:"Eliminate",body:"Charter, capital request and baseline data plan belong to other phases or activities."}],final:"Documentation plan often = final report → answer **B**",whyWrong:["Incorrect — a new charter is written in Define of the next project; it is not the documentation plan.","","Incorrect — capital requests relate to solution selection costs (5.3.1), not to the documentation plan.","Incorrect — the baseline data collection plan is a Measure-phase item."],bookRef:"Book p. 566"},{id:"sv-5-1230",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:3,stem:"The book says each player in the process has a role in **sustaining** project success. Which is NOT one of those roles?",options:["Accepting responsibility","Monitoring and responding","Sharing best practices","Adjusting the process after every reading that is not on target"],answer:3,hint:"Book p. 576, 'Organizational Change'.",steps:[{title:"Key idea",body:"Book p. 576: accept responsibility, monitoring, responding, managing, embracing change and continuous learning, sharing best practices, horizontal replication."},{title:"Find the outsider",body:"Adjusting after every off-target reading is tampering, which increases variation."}],final:"Tampering is not a sustaining role → answer **D**",whyWrong:["Incorrect — accepting responsibility IS listed.","Incorrect — monitoring and responding ARE listed.","Incorrect — sharing best practices IS listed.",""],bookRef:"Book pp. 544, 576"},{id:"sv-5-1231",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which statement about **knowledge tests** in the monitoring plan is CORRECT?",options:["They are run once, at go-live, and then removed from the plan","They check how people sample and measure, and are run after training and at regular or random intervals","They test the customer's knowledge of the new process","They replace the need for control charts on the process output"],answer:1,hint:"Book p. 569: when to sample, how to sample, how to measure.",steps:[{title:"Key idea",body:"Book p. 569: knowledge tests cover **when to sample** (after training, regular intervals, random intervals — often as audits), **how to sample** and **how to measure**."},{title:"Eliminate",body:"They are repeated, aimed at process staff, and sit alongside SPC."}],final:"Knowledge tests check sampling and measuring, repeatedly → answer **B**",whyWrong:["Incorrect — the book lists regular and random intervals as well as after training.","","Incorrect — the tests check the people running the process, not customers.","Incorrect — knowledge tests and SPC charts are separate parts of the monitoring plan."],bookRef:"Book p. 569"},{id:"sv-5-1232",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Implementation plans should emphasise the need to organise the tasks and [?], establish realistic time frames and identify the actions necessary to ensure success.`,options:["customers","measurements","resources","specifications"],answer:2,hint:"Book p. 562, first bullet.",steps:[{title:"Recall",body:"Book p. 562: organise the tasks and **resources**; establish realistic time frames and deadlines; identify actions necessary to ensure success."},{title:"Link",body:"Resources and tasks are what the work breakdown structure organises."}],final:"Resources → answer **C**",whyWrong:["Incorrect — customers are not organised by the implementation plan.","Incorrect — measurements belong to the monitoring plan.","","Incorrect — specifications come from the customer; they are not organised in the plan."],bookRef:"Book p. 562"},{id:"sv-5-1233",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which statement about **aligning systems and structures** is CORRECT?",options:["There are long- and short-term strategies for aligning systems and structures","It is complete once the SOPs have been updated","It applies only to incentive pay and not to job descriptions","It is the same as the monitoring plan"],answer:0,hint:"Book p. 572, the last line of the slide.",steps:[{title:"Key idea",body:"Book p. 572: systems and structures (goals, policies, job descriptions, incentive pay and programmes) allow people to change behaviour permanently, and 'there are **long- and short-term strategies** for alignment'."},{title:"Eliminate",body:"SOP updates are documentation; the element covers more than pay; it is a separate element."}],final:"Long- and short-term alignment strategies → answer **A**",whyWrong:["","Incorrect — updating SOPs is the documentation plan; alignment changes goals, policies and incentives.","Incorrect — job descriptions are explicitly listed alongside incentive compensation.","Incorrect — monitoring is a separate element that measures the process."],bookRef:"Book p. 572"},{id:"sv-5-1234",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:2,stem:`Put these Control-phase activities in the order the book lists them.

- **P** — Implement documentation plan
- **Q** — Develop training plan
- **R** — Develop documentation plan
- **S** — Implement training plan`,options:["Q → R → S → P","R → P → Q → S","Q → S → P → R","Q → S → R → P"],answer:3,hint:"Each plan is developed, then implemented, before the next plan starts.",steps:[{title:"Recall",body:"Book p. 578: Develop Training Plan → Implement Training Plan → Develop Documentation Plan → Implement Documentation Plan → …"},{title:"Apply",body:"Q → S → R → P."}],final:"Q → S → R → P → answer **D**",whyWrong:["Incorrect — the book implements the training plan before developing the documentation plan.","Incorrect — the training plan comes before the documentation plan in the book's list.","Incorrect — a plan cannot be implemented before it is developed.",""],bookRef:"Book p. 578"},{id:"sv-5-1235",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:2,stem:"All of the following are Control-phase **roadblocks** the book tells the team to plan for EXCEPT:",options:["Team members are not involved in control plan design","Management does not know the monitoring and reacting needs","Financial benefits are not tracked and integrated into the business","The process owner signs off the control plan"],answer:3,hint:"A roadblock stops the plan from working; one option is the cure.",steps:[{title:"Key idea",body:"Book p. 577 roadblocks: lack of sign-off, team not involved in control plan design, management lacking knowledge of monitoring and reacting, benefits not tracked, lack of operator buy-in."},{title:"Find the outsider",body:"Process-owner sign-off is the remedy for 'lack of project sign-off'."}],final:"Sign-off is a remedy, not a roadblock → answer **D**",whyWrong:["Incorrect — this IS a listed roadblock.","Incorrect — this IS a listed roadblock.","Incorrect — this IS a listed roadblock.",""],bookRef:"Book p. 577"},{id:"sv-5-1236",phase:5,topic:"5.3.2",qtype:"statements",difficulty:3,stem:`Which statements describe items the book lists under **control plan documentation** in the documentation plan?

1. Training manuals.
2. Job descriptions and performance management objectives.
3. The project charter.
4. The baseline Pareto chart from Define.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Book p. 567: training manuals; monitoring plan; response plan (FMEA); systems and structures (job descriptions, objectives).",steps:[{title:"Check each",body:"1 and 2 are on the list. 3 and 4 are Define-phase project records."},{title:"Match",body:"The true pair is 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — includes 3; the charter is not listed in the documentation plan.","Incorrect — 3 and 4 are both Define-phase records, not control plan documentation.","Incorrect — includes 4; the baseline Pareto is not listed."],bookRef:"Book p. 567"},{id:"sv-5-1237",phase:5,topic:"5.3.2",qtype:"statements",difficulty:2,stem:`Which statements describe how the book says control charts should be used in the monitoring plan?

1. Charts are kept at head office and updated at month end.
2. New control limits are set every quarter by habit.
3. Charts are posted in the area where the data are collected.
4. Actions taken to achieve in-control results are recorded.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Book p. 569: posted locally, plotted in real time, actions recorded, limits changed only on signals.",steps:[{title:"Check each",body:"3 and 4 match the book. 1 contradicts 'posted where data collected' and 'real time'. 2 contradicts 'new limits based on signals that performance has changed'."},{title:"Match",body:"The true pair is 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — 1 and 2 both contradict the book's charting guidance.","Incorrect — includes 2; limits change only on signals that performance has changed.","","Incorrect — includes 1; charts are posted where data are collected and plotted in real time."],bookRef:"Book p. 569"},{id:"sv-5-1238",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"In a typical control plan row, what does the **reaction plan** column refer to?",options:["The response-plan entry that says what to do when that characteristic signals","The specification limit agreed with the customer","The sample size and sampling frequency","The Gage R&R result for the measurement method"],answer:0,hint:"Each row links the control method to an agreed action.",steps:[{title:"Key idea",body:"Each control plan row ends with a **reaction plan reference**: the response-plan (or OCAP/FMEA) line describing what to do on a signal."},{title:"Eliminate",body:"Spec, sample size/frequency and MSA status are separate columns of the same row."}],final:"Reaction column → the response-plan entry → answer **A**",whyWrong:["","Incorrect — the specification has its own column and is the voice of the customer.","Incorrect — sample size and frequency have their own column in the row.","Incorrect — MSA status sits in the measurement-method column, not the reaction column."],bookRef:"Book pp. 564, 571"},{id:"sv-5-1239",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"According to the book, what is required before process staff can use the control charts in the monitoring plan properly?",options:["A new project charter","Training to interpret the charts and to respond to them","A capability index above 2.0","Approval from the external customer"],answer:1,hint:"Book p. 544, last bullet of 'Responding to Out of Control Indications'.",steps:[{title:"Key idea",body:"Book p. 544: '**Training is required** to interpret the charts and response to the charts.'"},{title:"Eliminate",body:"Charters, capability targets and customer approval do not teach anyone to read a chart."}],final:"Training to interpret and respond → answer **B**",whyWrong:["Incorrect — a charter starts a project; it does not prepare staff to read charts.","","Incorrect — capability is a separate measure; charts are used whatever the Cpk.","Incorrect — customers may ask for a control plan, but they do not train process staff."],bookRef:"Book p. 544"},{id:"sv-5-1240",phase:5,topic:"5.3.2",qtype:"statements",difficulty:2,stem:`Which statements describe what the book says should happen at the **project sign-off** meeting for the control plan?

1. The Belt keeps ownership of the plan after the meeting.
2. The specific changes to the process are highlighted.
3. Information is given on where the control plan is filed.
4. The control limits are recalculated from the pilot data.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Book p. 573: summary report, specific changes highlighted, where the plan is filed.",steps:[{title:"Check each",body:"2 and 3 are listed (with a summary report). 1 is wrong — ownership goes to the process owner. 4 is not a sign-off activity."},{title:"Match",body:"The true pair is 2 and 3."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — includes 1; the plan is handed to the process owner, not kept by the Belt.","","Incorrect — includes 4; recalculating limits is not part of the sign-off meeting.","Incorrect — 1 and 4 are both outside the book's sign-off list."],bookRef:"Book p. 573"},{id:"sv-5-1241",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Components of an implementation plan include a work [?] structure, an influence strategy, a risk management plan and an audit of results for completion and risks.`,options:["breakdown","cost","flow","value"],answer:0,hint:"Think of the project-management tool that splits work into tasks.",steps:[{title:"Recall",body:"Book p. 562: components of an implementation plan include a **work breakdown structure** (WBS)."},{title:"Link",body:"The WBS splits the solution into tasks that can be scheduled and assigned."}],final:"Breakdown → answer **A**",whyWrong:["","Incorrect — 'work cost structure' is not a book term.","Incorrect — workflow is a different idea; the book term is work breakdown structure.","Incorrect — value streams belong to Lean mapping, not the implementation plan."],bookRef:"Book p. 562"},{id:"sv-5-1242",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:3,stem:"Step Four of the book's Control checklist is *'Document what you have learned'*. Which question is NOT part of that step?",options:["Is there an updated FMEA?","Are there any spin-off projects?","What lessons have you learned?","What was the baseline sigma level in Measure?"],answer:3,hint:"Book p. 578, Step Four questions.",steps:[{title:"Key idea",body:"Book p. 578 Step Four: updated FMEA? control plan fully documented and implemented? financial implications? spin-off projects? lessons learned?"},{title:"Find the outsider",body:"The baseline sigma level is a Measure deliverable, not a Step Four question."}],final:"Baseline sigma is not a Step Four question → answer **D**",whyWrong:["Incorrect — 'Is there an updated FMEA?' IS a Step Four question.","Incorrect — spin-off projects ARE asked about in Step Four.","Incorrect — lessons learned ARE asked about in Step Four.",""],bookRef:"Book p. 578"},{id:"sv-5-1243",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"Halfway through Analyze, a Black Belt proposes drafting the **control plan** first and using it to work out which X's affect the dispute rate. Was this an appropriate action?",options:["Yes, because the control plan is the best tool for screening X's","Yes, because the control plan should be written before any data are collected","No, because the control plan documents controls for vital X's that have already been verified; finding the X's is Analyze work","No, because control plans are used only for manufacturing processes"],answer:2,hint:"Right tool, wrong phase.",steps:[{title:"Key idea",body:"The control plan is the last physical result of Control (p. 556). X's are proven in Analyze with hypothesis tests; the plan then controls them."},{title:"Decide",body:"Using the plan to find X's confuses Analyze with Control."}],final:"No — finding X's is Analyze → answer **C**",whyWrong:["Incorrect — screening X's uses the X-Y matrix, FMEA and hypothesis tests, not the control plan.","Incorrect — the plan is built from Measure and Analyze results, so it comes after data collection.","","Incorrect — control plans apply to service and transactional processes too."],bookRef:"Book pp. 556, 564"},{id:"sv-5-1244",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`The FMEA used for the monitoring plan, after recommended actions:

\`\`\`
FMEA – Fibre Activation (after actions)
Step        Failure mode              Cause (X)               SEV OCC DET RPN
Provision   ONT not provisioned       Order sync delay          8   5   4  160
Port assign Wrong port assigned       Manual port entry         7   2   2   28
Test        Line test skipped         Engineer bypasses test    9   2   3   54
Handover    Customer not informed     SMS template missing      4   3   2   24
\`\`\`

Which conclusion is CORRECT for the monitoring and response plans?`,options:["Order sync delay should be a priority trigger, because it has the highest remaining RPN","Manual port entry should be the main trigger, because it is a manual step","The SMS template should be the main trigger, because it affects the customer directly","No triggers are needed, because every RPN has been reduced"],answer:0,hint:"Triggers usually watch the highest-risk X's.",steps:[{title:"Read",body:"Remaining RPNs: 160, 28, 54, 24. The highest is 'order sync delay'."},{title:"Rule",body:"Book pp. 570–571: the FMEA feeds the monitoring plan, and response triggers usually monitor the **highest-risk X's**."}],final:"Highest remaining RPN = order sync delay → answer **A**",whyWrong:["","Incorrect — manual port entry has a low RPN of 28 after its actions.","Incorrect — the SMS template has the lowest RPN (24).","Incorrect — an RPN of 160 is still high risk and needs monitoring and a response."],bookRef:"Book pp. 570–571"},{id:"sv-5-1245",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which content does the book list for the **checklists and matrices** used in a monitoring plan?",options:["Control limits, centre line and the eight special-cause tests","Key items to check, decision criteria or a decision road map, and multi-variable tables","Severity, occurrence and detection ratings for each failure mode","Training modules, trainers and the training schedule"],answer:1,hint:"Checklists say what to check and how to decide.",steps:[{title:"Key idea",body:"Book p. 570: check lists/matrices contain **key items to check**, **decision criteria / decision road map** and **multi-variable tables**."},{title:"Eliminate",body:"Limits and tests = SPC charts; S/O/D = FMEA; modules and trainers = training plan outline."}],final:"Items to check, decision criteria, multi-variable tables → answer **B**",whyWrong:["Incorrect — control limits and tests belong to the SPC chart part of the monitoring plan.","","Incorrect — severity, occurrence and detection are FMEA ratings.","Incorrect — modules, trainers and schedules are columns of the training plan outline."],bookRef:"Book p. 570"},{id:"sv-5-1246",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"First-contact resolution, the primary metric, rose from 68% to 79%. The secondary metric, average handle time, has risen by 40% since go-live. The Belt wants to hand off and close today. What is the BEST action?",options:["Close the project, because the primary metric met its goal","Investigate the rise in handle time before closing, because the primary gain should not compromise the secondary metric","Remove handle time from the scorecard so it no longer conflicts","Recalculate the handle-time control limits so the rise looks normal"],answer:1,hint:"Book p. 574: success in the primary metric WITHOUT compromising the secondary metrics.",steps:[{title:"Key idea",body:"Book p. 574: has your project made success in the primary metric **without compromising your secondary metrics**?"},{title:"Apply",body:"A 40% rise in handle time is a compromise that must be understood before hand-off."}],final:"Resolve the secondary-metric impact first → answer **B**",whyWrong:["Incorrect — closing ignores the book's check on secondary metrics.","","Incorrect — removing the measure hides the problem instead of solving it.","Incorrect — resetting limits to absorb a deterioration hides a real change."],bookRef:"Book p. 574"},{id:"sv-5-1247",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:2,stem:"All of the following are goals of the Control phase given in the book EXCEPT:",options:["Assess the final process capability","Evaluate methods for defect prevention","Validate the root causes with hypothesis tests","Implement a control plan"],answer:2,hint:"Book p. 576, 'Control Phase Overview — The Goal'.",steps:[{title:"Key idea",body:"Book p. 576 goals: assess final capability, revisit Lean for sustaining, evaluate defect prevention, explore SPC monitoring, implement a control plan."},{title:"Find the outsider",body:"Validating root causes is Analyze."}],final:"Root-cause validation is Analyze → answer **C**",whyWrong:["Incorrect — assessing the final capability IS a Control goal.","Incorrect — evaluating defect-prevention methods IS a Control goal.","","Incorrect — implementing a control plan IS a Control goal."],bookRef:"Book p. 576"},{id:"sv-5-1248",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"How is the monitoring plan **sustained** after hand-off, according to the book?",options:["By training functional managers and making them accountable for adherence","By keeping the Belt in charge of every chart review","By recalculating the control limits at the start of each month","By replacing the charts with a final inspection step"],answer:0,hint:"Book p. 568, 'Sustaining the Monitoring Plan'.",steps:[{title:"Key idea",body:"Book p. 568: **functional managers** are responsible for adherence to the monitoring plan — they **must be trained** on how to do it and **made accountable** for adherence."},{title:"Eliminate",body:"The Belt develops the plan but moves on; routine recalculation and inspection are weaker practices."}],final:"Trained, accountable functional managers → answer **A**",whyWrong:["","Incorrect — the Belt develops the plan, but the control plan exists so the Belt can move on.","Incorrect — limits are changed only on signals that performance has changed, not by calendar.","Incorrect — final inspection is a weak Type 3 containment control, not how monitoring is sustained."],bookRef:"Book p. 568"},{id:"sv-5-1249",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:2,stem:"The new refund process goes live on Monday, although only half of the agents have been trained. The Belt plans to train the rest 'over the next quarter'. Was this an appropriate action?",options:["Yes, because training is optional when an SOP exists","Yes, because the response plan will catch any errors","No, because training belongs to the Define phase","No, because the training plan should set a timeline to train everyone on the new process before relying on it"],answer:3,hint:"Book p. 565: 'What is the timeline to train everyone on the new process(es)?'",steps:[{title:"Key idea",body:"Book p. 565: the training plan asks when training will be done and **what the timeline is to train everyone**."},{title:"Decide",body:"Running half-trained invites errors; an SOP alone is the weakest control."}],final:"No — train everyone to an agreed timeline → answer **D**",whyWrong:["Incorrect — an SOP alone is described as not sustainable; it does not replace training.","Incorrect — reacting to errors is weaker than preventing them through training.","Incorrect — the training plan is a Control-phase element.",""],bookRef:"Book pp. 522, 565"},{id:"sv-5-1250",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"How does a **control plan** differ from a process **FMEA**?",options:["The FMEA is written in Control; the control plan is written in Define","The FMEA is a living document; the control plan is fixed at closure","The FMEA assesses the risk of failure modes; the control plan documents the methods used to monitor and control the process","The FMEA replaces the SOPs; the control plan does not"],answer:2,hint:"One is a risk-ranking tool; the other is the written control system.",steps:[{title:"Key idea",body:"The FMEA ranks failure modes by RPN; the control plan is the written summary of how the process is monitored and controlled (p. 562), and it uses the FMEA as an input."},{title:"Eliminate",body:"Both are living documents, the control plan is a Control output, and neither replaces SOPs."}],final:"FMEA = risk; control plan = control methods → answer **C**",whyWrong:["Incorrect — the control plan is the last physical result of Control, not a Define document.","Incorrect — the book calls the control plan a living document, and the FMEA is also updated.","","Incorrect — the control plan is NOT a replacement for detailed instructions, and neither is the FMEA."],bookRef:"Book pp. 562, 570"},{id:"sv-5-1251",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which control method, written into a control plan row, does the book describe as **not sustainable** in the short term or the long term?",options:["A detection poka-yoke that stops the process","SPC on the critical X's run by empowered staff","A prevention poka-yoke that removes the error condition","An SOP alone that relies on people to detect defects"],answer:3,hint:"Recall the bottom rung of the control-strength ranking.",steps:[{title:"Key idea",body:"Book p. 522 ranks controls: prevention (Type 1) > flag/detection (Type 2) > SPC with empowered staff > SPC without empowerment / inspection > **SOP alone — not sustainable short-term or long-term**."},{title:"Apply",body:"A control plan should therefore prefer the strongest affordable control."}],final:"SOP alone is not sustainable → answer **D**",whyWrong:["Incorrect — a detection poka-yoke (Type 2 flag) is the second strongest control.","Incorrect — SPC with trained, empowered staff is a strong control in the ranking.","Incorrect — a prevention poka-yoke (Type 1) is the strongest control of all.",""],bookRef:"Book p. 522"},{id:"sv-5-1252",phase:5,topic:"5.3.2",qtype:"output",difficulty:2,stem:`The project closure checklist shows:

\`\`\`
Control Phase Closure – Repeat-Fault Project
Item                                         Status
Control plan documented and implemented      Yes
Control plan handed off to process owner     Yes
FMEA updated                                 Yes
Champion agrees project complete             Yes
Belt agrees project complete                 Yes
Finance agrees project complete              No
\`\`\`

Which conclusion is CORRECT?`,options:["The project is complete, because the control plan is handed off","The project is not yet complete, because Finance has not agreed","The project is complete, because the Champion has agreed","The FMEA must be redone before Finance can agree"],answer:1,hint:"Book p. 578: Champion, Belt AND Finance.",steps:[{title:"Read",body:"All items are 'Yes' except 'Finance agrees project complete'."},{title:"Rule",body:"Book p. 578: do the Champion, the Belt **and Finance** all agree the project is complete? Verify financial impact before the next project."}],final:"Finance has not agreed → not complete → answer **B**",whyWrong:["Incorrect — hand-off is necessary but not sufficient; all three must agree.","","Incorrect — the Champion's agreement alone is not enough.","Incorrect — the FMEA is already updated; the open item is the financial agreement."],bookRef:"Book pp. 577–578"},{id:"sv-5-1253",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`Extract from a draft control plan with the latest FMEA risk for each X:

\`\`\`
Control Plan Review – Order Activation
Row  Characteristic (X)        RPN   Control method
1    Address validated          36   System blocks invalid address
2    Credit check complete      48   p chart, staff empowered to stop
3    SIM-to-order match        210   SOP and annual training only
4    Tariff code entered        40   Drop-down list from master data
\`\`\`

Which conclusion is CORRECT?`,options:["Row 3 needs a stronger control, because the highest-risk X relies on an SOP and training only","Row 1 needs a stronger control, because a system block is the weakest method","Row 2 should be replaced by an SOP, because SPC is costly","No change is needed, because every row has a control method"],answer:0,hint:"Match the strength of the control to the size of the risk.",steps:[{title:"Read",body:"Row 3 has the highest RPN (210) but the weakest control (SOP + training). Rows 1 and 4 use prevention; row 2 uses empowered SPC."},{title:"Rule",body:"Book p. 522: SOP alone is not sustainable; the strongest affordable control should protect the highest-risk X."}],final:"Highest-risk X has the weakest control → row 3 → answer **A**",whyWrong:["","Incorrect — a system block is a prevention control, the strongest on the ladder.","Incorrect — an SOP alone ranks below SPC with empowered staff.","Incorrect — having a method is not enough; row 3's method is too weak for its risk."],bookRef:"Book pp. 522, 570"},{id:"sv-5-1254",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which **two uses** of documentation does the book name in the documentation plan?",options:["To calculate savings and to set bonuses","To screen X's and to choose the control chart","To define the scope and to select the team","To aid the implementation of solutions and for ongoing training"],answer:3,hint:"Book p. 566, two dashes under 'shared and institutionalised'.",steps:[{title:"Key idea",body:"Book p. 566: documentation is used to **aid implementation of solutions** and **for ongoing training**."},{title:"Eliminate",body:"Savings belong to Finance, X-screening to Analyze, scope and team to the charter."}],final:"Implementation aid and ongoing training → answer **D**",whyWrong:["Incorrect — savings are verified with Finance and bonuses belong to systems and structures.","Incorrect — screening X's is Analyze work; chart choice is part of SPC design.","Incorrect — scope and team selection are documented in the Define-phase charter.",""],bookRef:"Book p. 566"},{id:"sv-5-1255",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"How does an **implementation plan** differ from a **control plan**?",options:["The implementation plan lists the five elements; the control plan lists the work breakdown structure","The implementation plan is owned by the process owner; the control plan is owned by the supplier","The implementation plan organises tasks, resources and deadlines to put solutions in place; the control plan sustains the results afterwards","The implementation plan is a statistical tool; the control plan is a Lean tool"],answer:2,hint:"Book p. 562: first implement, then control.",steps:[{title:"Key idea",body:"Book p. 562: the implementation plan organises tasks and resources, sets realistic deadlines and includes a WBS, influence strategy, risk plan and audit. The control plan then sustains the gains."},{title:"Note",body:"The book adds that all solutions must be part of the control plan document."}],final:"Implement first, then control to sustain → answer **C**",whyWrong:["Incorrect — this swaps them: the WBS is in the implementation plan, the five elements in the control plan.","Incorrect — the control plan is handed to the process owner, not a supplier.","","Incorrect — both are planning documents; neither is classed this way in the book."],bookRef:"Book p. 562"},{id:"sv-5-1256",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:3,stem:"A project changed how the **billing tool** calculates late fees. The training plan covers the billing agents who use it. The IT application-support team, who handle tool tickets every day, are not included. What does the book suggest?",options:["Leave them out, because only people who run the process need training","Include them, because people who support the process impacted by the improvement need training","Train them only after a control chart signals","Leave them out, because IT owns no part of the control plan"],answer:1,hint:"Book p. 565: those impacted by the improvements.",steps:[{title:"Key idea",body:"Book p. 565: those impacted by the improvements include people **involved in** the process and people who **support** the process impacted by the improvement."},{title:"Apply",body:"Application support handles the changed tool, so it belongs in the training plan."}],final:"Train the support team too → answer **B**",whyWrong:["Incorrect — the book lists supporting staff as well as those running the process.","","Incorrect — training is planned before problems appear, not only after a signal.","Incorrect — supporters of the impacted process are named whether or not they own a control."],bookRef:"Book p. 565"},{id:"sv-5-1257",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The book's training plan outline records who will be trained, the trainers, the schedule and the final [?] of employee manuals.`,options:["approval","cost","location","version"],answer:2,hint:"Where will people find the manuals after the project?",steps:[{title:"Recall",body:"Book p. 566: the last column of the training plan outline is 'Final **Location** of Employee Manuals'."},{title:"Link",body:"Knowing where manuals live lets future trainers and new hires find them."}],final:"Location → answer **C**",whyWrong:["Incorrect — approval is not a column of the training plan outline.","Incorrect — cost is not a column of the training plan outline.","","Incorrect — version control matters, but the column is the final location of the manuals."],bookRef:"Book p. 566"},{id:"sv-5-1258",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In the monitoring plan, out-of-control signals on a control chart are acted on with guidelines from the [?].`,options:["CAR","FMEA","OCAP","SIPOC"],answer:2,hint:"Book p. 569: 'Act on Out of Control Response with guidelines from the…'",steps:[{title:"Recall",body:"Book p. 569: act on out-of-control response with guidelines from the **Out of Control Action Plan (OCAP)**, and record the actions taken."},{title:"Eliminate",body:"A CAR records a corrective action; the FMEA ranks risks; SIPOC scopes the process."}],final:"OCAP → answer **C**",whyWrong:["Incorrect — a CAR (Corrective Action Request) records the corrective action; it is not the guide on the chart.","Incorrect — the FMEA ranks failure modes; the OCAP gives the steps to follow on a signal.","","Incorrect — SIPOC is a high-level scoping tool from Define."],bookRef:"Book p. 569"},{id:"sv-5-1259",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:3,stem:"A control plan row reads: *Characteristic: daily repeat-fault rate · Control method: p chart · Owner: **Operations team** · Reaction: escalate.* An auditor says the row is weak. Which change BEST strengthens it?",options:["Name a specific role as owner and point the reaction to a defined response-plan entry","Replace the p chart with a monthly average","Remove the reaction column because the chart already shows signals","Widen the control limits to reduce escalations"],answer:0,hint:"'The team' is nobody; 'escalate' is not a defined response.",steps:[{title:"Key idea",body:"A control plan row needs a named owner and a reaction that points to the response plan's trigger, response, responsibility and documentation (p. 571)."},{title:"Apply",body:"Replace 'Operations team' with a role (e.g. repair duty manager) and 'escalate' with response-plan entry RP-xx."}],final:"Named owner + defined response → answer **A**",whyWrong:["","Incorrect — a monthly average hides the daily signals the chart is meant to show.","Incorrect — a chart only detects; the response plan says what to do.","Incorrect — limits come from process data; widening them hides real signals."],bookRef:"Book pp. 568, 571"},{id:"sv-5-1260",phase:5,topic:"5.3.2",qtype:"true-false",difficulty:1,stem:"True or False? The control plan should be written only **after** the project has been closed and the Belt has moved on.",options:["True","False"],answer:1,hint:"Who builds the plan, and when is it handed over?",steps:[{title:"Key idea",body:"The control plan is built by the team in Control and handed to the process owner before closure; the checklist asks 'Has the Control Plan been handed off to the process owner?' (p. 578)."},{title:"Decide",body:"It cannot be written after the team has gone — it is what allows the Belt to move on."}],final:"False → answer **B**",whyWrong:["Incorrect — the plan is created by the team and handed off before closure; it is what lets the Belt move on.",""],bookRef:"Book pp. 563, 578"},{id:"sv-5-1261",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Step One of the book's Control checklist is 'Process enhancement and control results'. Which question does it ask FIRST?",options:["Is there an updated FMEA?","How do the results of the improvements match the requirements of the business case and improvement goals?","Is the learning transferable across the business?","Are there any spin-off projects?"],answer:1,hint:"Step One starts by comparing results with the original business case.",steps:[{title:"Key idea",body:"Book p. 578, Step One: how do the results match the business case and goals? what are the vital few X's? how will you control or redesign them? is there a control plan? has it been handed to the process owner?"},{title:"Eliminate",body:"Updated FMEA and spin-offs are Step Four; transferable learning is Step Three."}],final:"Results vs business case come first → answer **B**",whyWrong:["Incorrect — the updated FMEA question belongs to Step Four, 'Document what you have learned'.","","Incorrect — transferable learning is asked in Step Three, standardisation and continuous improvement.","Incorrect — spin-off projects are asked about in Step Four."],bookRef:"Book p. 578"},{id:"sv-5-1262",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:3,stem:"After a repair project, field teams are judged on **two dashboards** that both track 'right first time' using slightly different definitions. Supervisors argue about which number is true. Which aligning-systems strategy from the book applies?",options:["Get rid of multiple measures for the same desired behaviour","Add a third dashboard to settle the difference","Increase the incentive linked to the higher number","Remove all measures of right first time"],answer:0,hint:"Book p. 573: four strategies about measures.",steps:[{title:"Key idea",body:"Book p. 573: get rid of measures not aligned with desired behaviour, **get rid of multiple measures for the same desired behaviour**, implement aligned measures not yet motivated, consider change management."},{title:"Apply",body:"Two measures of the same behaviour → keep one agreed measure."}],final:"Remove duplicate measures → answer **A**",whyWrong:["","Incorrect — a third measure adds to the duplication the book warns against.","Incorrect — rewarding the higher number encourages gaming rather than aligned behaviour.","Incorrect — right first time is the desired behaviour; it should be measured once, not dropped."],bookRef:"Book p. 573"},{id:"sv-5-1263",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which statement about **visual management** in the monitoring plan is CORRECT?",options:["Visual signals must be visual only and can never be audible","Visual management replaces the response plan","Red/yellow/green reports are used only during the Measure phase","5S is necessary for visual management to work"],answer:3,hint:"Book p. 570: alerts and signals, visual or audible, built on an organised workplace.",steps:[{title:"Key idea",body:"Book p. 570: visual management uses alerts or signals to trigger action; they **can be audible also**, and **5S is necessary** for visual management."},{title:"Eliminate",body:"Signals trigger the response; they do not replace it, and red/yellow/green reports are a Control monitoring tool."}],final:"5S underpins visual management → answer **D**",whyWrong:["Incorrect — the book states that the alerts can be audible as well.","Incorrect — a signal triggers action; the response plan still says what that action is.","Incorrect — the book lists red/yellow/green reports as a Control monitoring signal.",""],bookRef:"Book p. 570"},{id:"sv-5-1264",phase:5,topic:"5.3.2",qtype:"output",difficulty:2,stem:`The monitoring plan for repair time relies on technicians' recorded 'job complete' times. A Gage R&R on that measurement gives:

\`\`\`
Gage R&R – Job Complete Time
Source              %Contribution   %Study Var
Total Gage R&R          12.11          34.80
  Repeatability          7.29          27.00
  Reproducibility        4.82          21.95
Part-to-Part            87.89          93.75
Number of Distinct Categories = 3
\`\`\`

Which conclusion is CORRECT for the control plan?`,options:["The measurement system is acceptable because %Contribution is below 30%","The process is not capable, so the specification should be widened","The measurement system is unacceptable, so it should be improved before chart signals are trusted","The control limits should be recalculated using %Study Var"],answer:2,hint:"Judge %Study Var against the <10 / 10–30 / >30 bands.",steps:[{title:"Read",body:"Total Gage R&R %Study Var = 34.80% (> 30%) and ndc = 3."},{title:"Decide",body:"Above 30% is unacceptable; a control plan row needs an adequate measurement method before its chart can be relied on."}],final:"%Study Var 34.8% → fix the measurement first → answer **C**",whyWrong:["Incorrect — the 10/30% bands are applied to %Study Var, not to %Contribution.","Incorrect — Gage R&R judges the measurement system, not process capability.","","Incorrect — control limits come from process data, not from the Gage R&R table."],trap:"Gage R&R = measurement system; Cpk = process. Do not swap them.",bookRef:"Book p. 562; Syllabus 2.3.3"},{id:"sv-5-1265",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:2,stem:`Put these training-plan activities in a logical order.

- **P** — Build the module into new-employee orientation
- **Q** — Identify who requires training
- **R** — Deliver the training to the agreed timeline
- **S** — Develop the training materials`,options:["Q → S → R → P","S → Q → R → P","Q → R → S → P","Q → S → P → R"],answer:0,hint:"Who → what → deliver → keep it going.",steps:[{title:"Key idea",body:"Book pp. 565–566: who requires training → specific materials developed → when and the timeline to train everyone → what triggers ongoing training (new-employee orientation)."},{title:"Apply",body:"Q → S → R → P."}],final:"Q → S → R → P → answer **A**",whyWrong:["","Incorrect — materials are designed for an audience, so the trainees are identified first.","Incorrect — training cannot be delivered before its materials are developed.","Incorrect — ongoing orientation follows the first delivery of the training."],bookRef:"Book pp. 565–566"},{id:"sv-5-1266",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Under the training plan, who does the book say is responsible for the planning, development and execution of the **immediate** training on the new process?",options:["The Finance department","The external customer","The project team","The Master Black Belt"],answer:2,hint:"Separate immediate training (at go-live) from ongoing training (after hand-off).",steps:[{title:"Key idea",body:"Book p. 565: immediate training is the **responsibility of the project team**; ongoing training is typically owned by a training department or the process owner."},{title:"Eliminate",body:"Finance validates savings, customers receive the output, and the MBB coaches Belts."}],final:"Immediate training = project team → answer **C**",whyWrong:["Incorrect — Finance validates the financial benefits; it does not plan process training.","Incorrect — the customer receives the output and is not responsible for training process staff.","","Incorrect — the MBB coaches and mentors Belts; the book gives immediate training to the project team."],trap:"Ongoing training moves to qualified trainers (training department or process owner).",bookRef:"Book p. 565"},{id:"sv-5-1267",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Why does the book say control plans **'may not be exciting'**?",options:["They are written only by the Finance department","Nothing new is done to the process; the plan stabilises it for the future","They contain no statistical tools","They are optional when the process is already capable"],answer:1,hint:"Improve changes the process; Control holds it still.",steps:[{title:"Key idea",body:"Book p. 564 margin: control plans may not be exciting because **you are not doing anything new** to the process — you are **stabilising** it for the future."},{title:"Eliminate",body:"The plan is team-built, includes SPC and FMEA, and is needed even for capable processes."}],final:"It stabilises rather than changes → answer **B**",whyWrong:["Incorrect — the project team and process stakeholders create the plan, not Finance alone.","","Incorrect — the monitoring plan includes SPC charts and the FMEA.","Incorrect — a capable process still needs controls to stay capable; the plan is not optional."],bookRef:"Book p. 564"},{id:"sv-5-1268",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which statement about **ongoing responsibility** in the documentation plan is CORRECT?",options:["The Belt remains responsible for updating every document after the project closes","Documents are reviewed only when an auditor asks for them","Ongoing responsibility is identical in every organisation","The plan must name who makes updates as changes occur and who reviews documents for currency and accuracy"],answer:3,hint:"Book p. 567: 'organizationally based' ongoing responsibility.",steps:[{title:"Key idea",body:"Book p. 567: for the ongoing process (organisationally based) the plan **must outline who updates/modifies documents** and **who reviews them** for currency and accuracy."},{title:"Eliminate",body:"The Belt's duty ends at hand-off; reviews are regular; responsibility depends on the organisation."}],final:"Name the updater and the reviewer → answer **D**",whyWrong:["Incorrect — the Belt ensures documents are current at hand-off; ongoing updates go to named owners.","Incorrect — the book asks for a process to review documents on a regular basis.","Incorrect — the book calls ongoing responsibility 'organizationally based'.",""],bookRef:"Book p. 567"},{id:"sv-5-1269",phase:5,topic:"5.3.2",qtype:"output",difficulty:2,stem:`After a repeat-fault project, the team reviews the field scorecard:

\`\`\`
Field Technician Scorecard – Measures
Measure                          Rewards desired behaviour?
Repeat faults within 30 days     Yes
First-visit fix rate             Yes
Jobs closed per hour             No (rewards rushed closures)
Customer callback score          Yes
\`\`\`

Which action does the book's aligning-systems guidance support?`,options:["Remove or replace 'jobs closed per hour', because it is not aligned with the desired behaviour","Add a second measure of jobs closed per day","Remove 'repeat faults within 30 days', because it is already in the control plan","Leave all measures as they are, because most are aligned"],answer:0,hint:"Book p. 573: get rid of measures not aligned with desired behaviours.",steps:[{title:"Read",body:"Only 'jobs closed per hour' is marked as not rewarding the desired behaviour."},{title:"Rule",body:"Book p. 573: **get rid of measurements not aligned with desired behaviours** and ask whether hourly incentives hurt success."}],final:"Remove the misaligned hourly measure → answer **A**",whyWrong:["","Incorrect — a second closure measure duplicates the misaligned one.","Incorrect — repeat faults is an aligned measure of the project goal.","Incorrect — one misaligned measure can undo the gains, so it must be addressed."],bookRef:"Book p. 573"},{id:"sv-5-1270",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:2,stem:"An operator collects the daily fill-weight readings on paper and **plots them on the control chart every Friday**. Was this an appropriate practice under the monitoring plan?",options:["Yes, because weekly plotting reduces the risk of tampering","Yes, because control charts only need to be reviewed at month end","No, because points should be plotted in real time so that out-of-control signals can be acted on at once","No, because fill weight should be checked against the specification only"],answer:2,hint:"Book p. 569: posted where data are collected, plotted real time.",steps:[{title:"Key idea",body:"Book p. 569: control charts are posted where data are collected and **points are plotted in real time**, acting on the OCAP; p. 544 adds that special causes need an immediate response."},{title:"Decide",body:"Weekly plotting delays every response by up to a week."}],final:"No — plot in real time → answer **C**",whyWrong:["Incorrect — tampering is avoided by following the rules, not by delaying the plot.","Incorrect — month-end review delays the immediate response the book requires.","","Incorrect — control charts monitor stability; specs alone do not show special causes."],bookRef:"Book pp. 544, 569"},{id:"sv-5-1271",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A service-desk project found that updating knowledge articles drives first-contact resolution. Agents are measured on calls handled, but **nothing measures or rewards updating articles**. Which aligning-systems action fits the book?",options:["Remove the knowledge base from the control plan","Implement a measure aligned with the desired behaviour that is not yet motivated","Add a control chart of the agents' break times","Rewrite the project charter"],answer:1,hint:"A desired behaviour with no measure behind it.",steps:[{title:"Key idea",body:"Book p. 573: **implement measures aligned with desired behaviours currently not motivated by incentives**."},{title:"Apply",body:"Add a measure (and recognition) for timely knowledge-article updates."}],final:"Add a measure for the desired behaviour → answer **B**",whyWrong:["Incorrect — the knowledge base is a vital X; removing it from the plan loses control of it.","","Incorrect — break times are unrelated to the desired behaviour.","Incorrect — the charter is a Define document; the gap is in systems and structures."],bookRef:"Book p. 573"},{id:"sv-5-1272",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which statement about the **training plan** is CORRECT?",options:["Training is needed only for operators who run the process today","Once the first round of training is delivered, the training plan is closed","Training is the responsibility of the Finance department","Specific training materials, such as presentations, on-the-job checklists and exercises, need developing"],answer:3,hint:"Book p. 565 lists materials, a timeline and triggers for ongoing training.",steps:[{title:"Key idea",body:"Book p. 565: 'Specific training **materials** need developing — PowerPoint, On the Job Checklist, Exercises, etc.'"},{title:"Eliminate",body:"The plan also covers support staff and future process changers, and ongoing training triggers."}],final:"Training materials must be developed → answer **D**",whyWrong:["Incorrect — it also covers people who support the process and those who will change it in future.","Incorrect — the plan defines triggers for ongoing training such as new-hire orientation and refreshers.","Incorrect — the project team delivers immediate training; ongoing training goes to qualified trainers.",""],bookRef:"Book p. 565"},{id:"sv-5-1273",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"The book sums up the reason for a control plan as **'going for distance, not the sprint'**. What does this mean?",options:["The project should be completed as fast as possible","The control plan should be written before the Measure phase","Only long-term capability (Ppk) should be reported","The aim is to sustain the gains long after the project, not only to achieve them once"],answer:3,hint:"Sustain versus achieve.",steps:[{title:"Key idea",body:"Book p. 563: project results need to be **sustained**; the slogan contrasts lasting control with a one-off success."},{title:"Eliminate",body:"Speed, timing in Measure and Ppk reporting are not what the slogan refers to."}],final:"Sustain the gains over time → answer **D**",whyWrong:["Incorrect — speed of completion is the 'sprint' the slogan warns against.","Incorrect — the control plan is built in Control, using results from earlier phases.","Incorrect — the slogan is about sustaining results, not about choosing a capability index.",""],bookRef:"Book p. 563"},{id:"sv-5-1274",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:3,stem:"A project cut porting errors at one region. The Control checklist asks *'Is the learning transferable across the business?'* Two other regions run the same process. What is the BEST use of the control plan here?",options:["Keep it confidential to the original region","Use it and its documentation as the basis for sharing the best practice and replicating the results horizontally","Restart the other regions at the Define phase with a new charter","Copy only the control limits to the other regions' charts"],answer:1,hint:"Book pp. 576, 578: sharing best practices, horizontal replication.",steps:[{title:"Key idea",body:"Book p. 578, Step Three: is the learning transferable? what is the action plan for spreading the best practice? Book p. 576 lists **horizontal replication**."},{title:"Apply",body:"The documented controls give the other regions a tested starting point."}],final:"Share and replicate horizontally → answer **B**",whyWrong:["Incorrect — the book encourages sharing best practice, not restricting it.","","Incorrect — a full new project ignores proven learning that can be transferred.","Incorrect — control limits come from each region's own process data and cannot simply be copied."],bookRef:"Book pp. 576, 578"},{id:"sv-5-1275",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:1,stem:`Put these steps of the book's DMAIC roadmap in order.

- **P** — Implement control plan to ensure the problem does not return
- **Q** — Prove or disprove the impact the X's have on the problem
- **R** — Verify financial impact
- **S** — Implement solutions to control or eliminate the X's`,options:["S → Q → P → R","Q → P → S → R","Q → S → P → R","Q → S → R → P"],answer:2,hint:"Analyze → Improve → Control → money.",steps:[{title:"Recall",body:"Book p. 577: Analyze proves/disproves X's; Improve implements solutions; Control implements the control plan, then verifies financial impact."},{title:"Apply",body:"Q → S → P → R."}],final:"Q → S → P → R → answer **C**",whyWrong:["Incorrect — solutions are implemented only after the X's are proven in Analyze.","Incorrect — the control plan follows the implemented solutions, it does not precede them.","","Incorrect — the financial impact is verified after the control plan is in place."],bookRef:"Book p. 577"},{id:"sv-5-1276",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"What does the book give as the purpose of the **documentation plan**?",options:["To ensure that what has been learned from the project is shared and institutionalised","To decide what to do when a chart shows an out-of-control signal","To align incentive pay with the new behaviour","To rank solutions by impact, cost and time"],answer:0,hint:"Documentation turns project knowledge into organisational knowledge.",steps:[{title:"Key idea",body:"Book p. 566: documentation is necessary to ensure **what has been learned from the project is shared and institutionalised**."},{title:"Eliminate",body:"Out-of-control actions = response plan; incentives = aligning systems; ranking solutions = Improvement Selection Matrix."}],final:"Share and institutionalise the learning → answer **A**",whyWrong:["","Incorrect — reacting to out-of-control signals is the job of the response plan.","Incorrect — aligning incentives is the 'aligning systems and structures' element.","Incorrect — ranking solutions by impact, cost and time is the Improvement Selection Matrix (5.3.1)."],bookRef:"Book p. 566"},{id:"sv-5-1277",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"According to the book's closing advice for the Control phase, what gives a project the **greatest chance of success**?",options:["Keeping the control plan within the project team until the results are final","Reporting only the primary metric to the Champion","Involving team members who work in the process and keeping the Champion and process owner updated on results","Letting the Belt make all control decisions alone"],answer:2,hint:"A basic change-management idea from Define, repeated at the end of Control.",steps:[{title:"Key idea",body:"Book p. 574: involve team members who work in the process and keep the project Champion and process owner updated — then you have the greatest chance of success."},{title:"Eliminate",body:"Secrecy, partial reporting and solo decisions all work against buy-in."}],final:"Involve process workers; keep Champion and owner updated → answer **C**",whyWrong:["Incorrect — withholding the plan blocks buy-in; lack of buy-in is a listed roadblock.","Incorrect — the book asks whether the primary metric improved WITHOUT compromising the secondary metrics.","","Incorrect — the plan is created by the team and everyone with a role in the process."],bookRef:"Book pp. 574, 577"},{id:"sv-5-1278",phase:5,topic:"5.3.2",qtype:"statements",difficulty:2,stem:`Which statements describe triggers for **ongoing training** given in the book's training plan?

1. New-employee orientation.
2. Each time a single point falls above the centre line.
3. Approval of next year's capital budget.
4. Refresher training.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Book p. 565: 'What will trigger ongoing training?'",steps:[{title:"Check each",body:"1 and 4 are on the book's list (with the response plan when performance degrades). 2 is ordinary common-cause variation, and 3 is a budget event."},{title:"Match",body:"The true pair is 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — includes 2; a point above the centre line is not a signal and not a training trigger.","Incorrect — 2 and 3 are both outside the book's triggers.","Incorrect — includes 3; budget approval is not a training trigger.",""],bookRef:"Book p. 565"},{id:"sv-5-1279",phase:5,topic:"5.3.2",qtype:"output",difficulty:2,stem:`Minitab output and the chart's action log for a p chart in the monitoring plan:

\`\`\`
Test Results for P Chart of Failed Activations
TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  14, 27

Action log
Point 14: supplier SIM batch quarantined, process back in control
Point 27: (no entry)
\`\`\`

Which conclusion is CORRECT?`,options:["Point 27 can be ignored because point 14 was already explained","The control limits should be recalculated without points 14 and 27","Both points are common-cause variation because only Test 1 failed","The action for point 27 should be found and recorded, because actions taken to restore control must be recorded"],answer:3,hint:"Book p. 569: 'Record actions taken to achieve in-control results.'",steps:[{title:"Read",body:"Test 1 failed at 14 and 27; only 14 has an action recorded."},{title:"Rule",body:"Book p. 569: act on OCAP guidance and **record actions taken** to achieve in-control results."}],final:"Record the action for point 27 → answer **D**",whyWrong:["Incorrect — each signal needs its own investigation and record.","Incorrect — removing points without a recorded, removed cause hides information.","Incorrect — a Test 1 failure is a special-cause signal, not common-cause variation.",""],bookRef:"Book pp. 544, 569"},{id:"sv-5-1280",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:1,stem:"Which is NOT a column of the book's **training plan outline**?",options:["Who will be trained","RPN after actions","Trainer(s)","Integration into ongoing new-employee training"],answer:1,hint:"Book p. 566: module, creators, schedule, trainees, trainers, integration, manual location.",steps:[{title:"Key idea",body:"Book p. 566 columns: training module, who will create modules, schedule for module completion, who will be trained, schedule for training, trainer(s), integration into ongoing new-employee training, final location of employee manuals."},{title:"Find the outsider",body:"RPN after actions is an FMEA column."}],final:"RPN belongs to the FMEA → answer **B**",whyWrong:["Incorrect — 'Who will be trained' IS a column.","","Incorrect — 'Trainer(s)' IS a column.","Incorrect — integration into new-employee training IS a column."],bookRef:"Book p. 566"},{id:"sv-5-1281",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"At implementation, who does the book say ensures that all documents are **current at hand-off**?",options:["The Belt","The functional manager","The Finance representative","The external auditor"],answer:0,hint:"The book splits documentation responsibility into 'at implementation' and 'ongoing'.",steps:[{title:"Key idea",body:"Book p. 567: at implementation the **Belt** ensures documents are current at hand-off, that a process exists to modify them, and that a process exists to review them."},{title:"Apply",body:"Ongoing updates and reviews are then assigned by the organisation, as the plan must outline."}],final:"Belt ensures documents are current at hand-off → answer **A**",whyWrong:["","Incorrect — functional managers own adherence to the monitoring plan, not hand-off documentation.","Incorrect — Finance verifies financial impact; it does not check document currency.","Incorrect — an auditor may check documents later but is not given hand-off responsibility in the book."],bookRef:"Book p. 567"},{id:"sv-5-1282",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:3,stem:`Put the four steps of the book's **Control phase checklist** in order.

- **P** — Standardisation and continuous improvement
- **Q** — Document what you have learned
- **R** — Process enhancement and control results
- **S** — Capability analysis for X and Y`,options:["R → S → P → Q","S → R → P → Q","R → P → S → Q","R → S → Q → P"],answer:0,hint:"Results first, capability second, standardise third, document last.",steps:[{title:"Recall",body:"Book p. 578: Step One Process Enhancement and Control Results; Step Two Capability Analysis for X and Y; Step Three Standardization and Continuous Improvement; Step Four Document what you have learned."},{title:"Apply",body:"R → S → P → Q."}],final:"R → S → P → Q → answer **A**",whyWrong:["","Incorrect — the checklist starts with the control results before capability.","Incorrect — capability (Step Two) comes before standardisation (Step Three).","Incorrect — documenting what was learned is the last step."],bookRef:"Book p. 578"},{id:"sv-5-1283",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"A control plan says: *'If the chart signals, the shift lead stops new activations and calls the provisioning engineer.'* Which control plan element is this?",options:["Training plan","Documentation plan","Aligning systems and structures","Response plan"],answer:3,hint:"What to do when monitoring shows a signal.",steps:[{title:"Key idea",body:"The response plan outlines the process to follow when there is a defect or out-of-control condition — trigger, response and responsibility (p. 571)."},{title:"Apply",body:"Stopping activations and calling the engineer on a signal is a response."}],final:"Action on a signal = response plan → answer **D**",whyWrong:["Incorrect — the training plan teaches people; it does not define the action on a signal.","Incorrect — the documentation plan keeps documents current and reviewed.","Incorrect — aligning systems covers goals, policies, job descriptions and incentives.",""],bookRef:"Book p. 571"},{id:"sv-5-1284",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:1,stem:"Fibre-splicing technicians ask for a **one-page sheet** at each workstation showing what to check, how often and what limits apply. Which document should this sheet be created from?",options:["The project charter","The SIPOC","The control plan","The cause-and-effect diagram"],answer:2,hint:"Book p. 562: 'often used to create…'",steps:[{title:"Key idea",body:"Book p. 562: the control plan is **often used to create a concise operator inspection sheet**."},{title:"Eliminate",body:"Charter, SIPOC and fishbone are Define/Analyze tools that hold no checks or limits."}],final:"Operator sheet comes from the control plan → answer **C**",whyWrong:["Incorrect — the charter records the project problem, goal and scope.","Incorrect — the SIPOC shows the high-level process scope, not checks and limits.","","Incorrect — the fishbone lists potential causes; it does not define routine checks."],bookRef:"Book p. 562"},{id:"sv-5-1285",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"A control plan states that the new number-porting procedure will be included in **new-employee orientation**. Which control plan element is this?",options:["Monitoring plan","Training plan","Response plan","Documentation plan"],answer:1,hint:"What will trigger ongoing training?",steps:[{title:"Key idea",body:"Book p. 565: the training plan asks **what will trigger ongoing training** — new-employee orientation, refresher training, or the response plan when performance degrades."},{title:"Apply",body:"Building the procedure into orientation is a training-plan decision."}],final:"Orientation module = training plan → answer **B**",whyWrong:["Incorrect — the monitoring plan decides what is measured, how and when.","","Incorrect — the response plan says what to do when monitoring shows a defect or signal.","Incorrect — the documentation plan keeps documents current; it does not schedule training."],bookRef:"Book pp. 565–566"},{id:"sv-5-1286",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"A year after closure, the repeat-visit rate has returned to its old level. The new process owner wants to start a fresh DMAIC project at once. What should be done FIRST?",options:["Start a new Define phase with a new charter","Retrieve the filed control plan and use it as the reference for the unsustained results","Recalculate the control limits so the current rate looks normal","Replace all controls with 100% inspection"],answer:1,hint:"Book p. 562: filed to track benefits and as a reference for unsustained results.",steps:[{title:"Key idea",body:"Book p. 562: the control plan is filed in the project tracking mechanism to **track benefits** and as a **reference for unsustained results**."},{title:"Apply",body:"Start by checking which controls in the plan stopped working."}],final:"Use the control plan as the reference first → answer **B**",whyWrong:["Incorrect — a new project may follow, but the plan shows first which control failed.","","Incorrect — resetting limits to the worse level hides the loss of the gain.","Incorrect — inspection is weak containment and ignores what the plan already says."],bookRef:"Book p. 562"},{id:"sv-5-1287",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"According to the book, which is a reason an organisation needs a control plan?",options:["It proves which X's have a significant effect on the Y","It sets the baseline sigma level of the process","It allows the Belt to move on to other projects","It replaces the need for a process owner"],answer:2,hint:"Think about what happens to the Belt and the gains after the project closes.",steps:[{title:"Key idea",body:"The book's reasons (p. 563): results must be sustained, people follow the designated control methods, **the Belt can move on to other projects**, no need for 'constant heroes', and customers increasingly require it."},{title:"Eliminate",body:"Proving X's is Analyze, baseline sigma is Measure, and the process owner is the one who takes over the plan."}],final:"The plan frees the Belt for new projects → answer **C**",whyWrong:["Incorrect — proving which X's matter is done with hypothesis tests in Analyze, before the control plan exists.","Incorrect — the baseline sigma level is a Measure-phase output, not a reason for a control plan.","","Incorrect — the control plan is handed to the process owner, who is accountable for sustaining it."],bookRef:"Book p. 563"},{id:"sv-5-1288",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which statement about control plans for **service and transactional** processes is CORRECT?",options:["They are needed as much as in manufacturing, because any process can drift back after the project","They are not needed, because service processes cannot be measured","They are needed only when a machine is involved","They are replaced by customer complaints as the only monitor"],answer:0,hint:"The book's own examples include a call centre and a hotel.",steps:[{title:"Key idea",body:"Project results must be sustained in every process (p. 563); the book's examples include paycheck rework, phone-bank response time and hotel services."},{title:"Eliminate",body:"Service processes are measured with p charts, I charts and checklists like any other."}],final:"Service processes need control plans too → answer **A**",whyWrong:["","Incorrect — service outputs such as response time or rework rate are measured and charted in the book.","Incorrect — the book's examples include call centres and paycheck processing.","Incorrect — waiting for complaints is the weakest, most delayed form of detection."],bookRef:"Book pp. 544, 561, 563"},{id:"sv-5-1289",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"A warehouse control plan says: *'Return the empty bin to the replenishment point; an empty bin is the signal to restock.'* Which part of the control plan does this belong to?",options:["The documentation plan","Aligning systems and structures","The training plan","Visual management in the monitoring plan"],answer:3,hint:"An alert or signal that triggers action.",steps:[{title:"Key idea",body:"Book p. 570: visual management = **alerts or signals that trigger action**, e.g. empty bins returned when stock needs replenishing, or red/yellow/green reports."},{title:"Apply",body:"It sits in the **monitoring plan**, next to SPC, FMEA and checklists."}],final:"Empty-bin signal = visual management (monitoring plan) → answer **D**",whyWrong:["Incorrect — the documentation plan lists and maintains documents; it does not signal action on the floor.","Incorrect — systems and structures cover goals, policies, job descriptions and incentives.","Incorrect — the training plan covers who is trained, by whom and when.",""],bookRef:"Book p. 570"},{id:"sv-5-1290",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

The five elements of a control plan are documentation, monitoring, response, training and [?].`,options:["aligning systems and structures","capability analysis","hypothesis testing","root cause analysis"],answer:0,hint:"Book p. 564: the element about goals, policies and incentives.",steps:[{title:"Recall",body:"Book p. 564: 'The 5 elements of a Control Plan include the documentation, monitoring, response, training and **aligning systems and structures**.'"},{title:"Eliminate",body:"The other options are analysis activities from Measure and Analyze."}],final:"Aligning systems and structures → answer **A**",whyWrong:["","Incorrect — capability analysis is assessed in Measure and Control, but it is not a control plan element.","Incorrect — hypothesis testing belongs to Analyze.","Incorrect — root cause analysis is Analyze work done before the control plan."],bookRef:"Book p. 564"},{id:"sv-5-1291",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Team leaders' annual **performance objectives** are rewritten to include first-contact resolution, the project's Y. Which control plan element is this?",options:["Monitoring plan","Response plan","Training plan","Aligning systems and structures"],answer:3,hint:"Goals and objectives make the new behaviour permanent.",steps:[{title:"Key idea",body:"Book p. 572: systems and structures — **performance goals/objectives**, policies, job descriptions, incentive pay and programmes — are the basis for permanent behaviour change."},{title:"Apply",body:"Rewriting performance objectives is aligning systems and structures."}],final:"Performance objectives = aligning systems and structures → answer **D**",whyWrong:["Incorrect — the monitoring plan measures FCR; it does not set people's objectives.","Incorrect — the response plan acts on signals; it does not change objectives.","Incorrect — the training plan teaches the new method; objectives belong to systems and structures.",""],bookRef:"Book p. 572"},{id:"sv-5-1292",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:3,stem:"A draft control plan protects invoice accuracy by having a clerk **check 100% of invoices** before they are sent. A system validation rule that blocks bad invoices is being built and will take two months. How should the 100% check be classed in the control plan?",options:["As short-term containment by inspection until the stronger control is in place","As a Type 1 countermeasure that removes the error condition","As the strongest permanent control available","As a detection poka-yoke that stops the process"],answer:0,hint:"Type 3 = inspection, short-term containment.",steps:[{title:"Key idea",body:"Book p. 522: Type 3 corrective action — **inspection** — is short-term containment likely to find the defect after it occurs."},{title:"Apply",body:"100% manual checking is containment until the validation rule (a stronger control) goes live."}],final:"100% check = Type 3 containment → answer **A**",whyWrong:["","Incorrect — a Type 1 countermeasure makes the error impossible; a clerk's check does not.","Incorrect — inspection ranks near the bottom of the control ladder.","Incorrect — a detection poka-yoke is automatic and stops the process; a manual check is inspection."],bookRef:"Book p. 522"},{id:"sv-5-1293",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A Black Belt invites a **Human Resources** representative to the control plan workshop for a billing project. A team member asks why HR is needed. What is the BEST reason?",options:["HR must calculate the control limits for the new charts","HR is the process owner for every process in the company","Anyone with a role in defining, executing or changing the process should help create the plan, and HR owns job descriptions and incentives","HR must approve the hypothesis tests used in Analyze"],answer:2,hint:"Book p. 563: who should create a control plan.",steps:[{title:"Key idea",body:"Book p. 563: the team plus ANYONE with a role in defining, executing or changing the process — associates, technical experts, supervisors, managers, site manager, **Human Resources**."},{title:"Apply",body:"HR controls job descriptions and incentive pay, which the 'aligning systems and structures' element changes."}],final:"HR shapes systems and structures → answer **C**",whyWrong:["Incorrect — control limits are calculated from process data by the team, not by HR.","Incorrect — the process owner is the manager of the billing process, not HR.","","Incorrect — HR has no role in approving Analyze-phase statistics."],bookRef:"Book pp. 563, 572"},{id:"sv-5-1294",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"Until a system validation rule is ready in two months, the control plan uses a **100% manual check** of new SIM activations, marked as temporary. Was this an appropriate action?",options:["Yes, because 100% inspection is the strongest long-term control","Yes, because inspection can serve as short-term containment while a stronger control is put in place","No, because inspection can never appear in a control plan","No, because the process must stay unprotected until the validation rule is live"],answer:1,hint:"Type 3 = short-term containment.",steps:[{title:"Key idea",body:"Book p. 522: Type 3 inspection is **short-term containment**; Type 1/2 poka-yoke controls are stronger and permanent."},{title:"Decide",body:"Using inspection as a labelled, temporary bridge to a stronger control is sound."}],final:"Yes — temporary containment is appropriate → answer **B**",whyWrong:["Incorrect — inspection is a weak control, ranked below poka-yoke and empowered SPC.","","Incorrect — inspection is allowed as containment; it is just not the permanent answer.","Incorrect — leaving the process unprotected lets defects reach customers."],bookRef:"Book p. 522"},{id:"sv-5-1295",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:2,stem:`Put these steps in order, from choosing a solution to closing the project.

- **P** — Develop and implement the control plan elements
- **Q** — Build the implementation plan (WBS, risk plan, deadlines)
- **R** — Verify the financial impact
- **S** — Rate the potential improvements in the Improvement Selection Matrix`,options:["Q → S → P → R","S → Q → P → R","S → P → Q → R","S → Q → R → P"],answer:1,hint:"Select → plan the implementation → control → money.",steps:[{title:"Recall",body:"Book pp. 559–564: the selection matrix picks the improvement; the implementation plan organises it; the control plan elements sustain it; then verify financial impact."},{title:"Apply",body:"S → Q → P → R."}],final:"S → Q → P → R → answer **B**",whyWrong:["Incorrect — the improvement must be selected before its implementation is planned.","","Incorrect — the implementation plan comes before the control plan elements.","Incorrect — the financial impact is verified after the control plan is in place."],bookRef:"Book pp. 559–564, 578"},{id:"sv-5-1296",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"The book's Control checklist asks *'How is this referenced in process procedures and product drawings?'* What is the PRIMARY purpose of this question?",options:["To check that the control limits are printed on the drawings","To confirm that Finance has approved the savings","To make sure the change is built into the standard documents so it is not lost or reinvented","To decide which hypothesis test proved the root cause"],answer:2,hint:"Step Three: standardisation and continuous improvement.",steps:[{title:"Key idea",body:"Book p. 578, Step Three asks how the problem is kept from returning, whether there is a project documentation file, how it is referenced in procedures and drawings, and what stops it being reinvented."},{title:"Apply",body:"Referencing the change in procedures and drawings standardises it."}],final:"Standardise the change in core documents → answer **C**",whyWrong:["Incorrect — control limits belong on the control charts, not on product drawings.","Incorrect — Finance agreement is a separate General Question in the checklist.","","Incorrect — root-cause testing was completed in Analyze."],bookRef:"Book p. 578"},{id:"sv-5-1297",phase:5,topic:"5.3.2",qtype:"true-false",difficulty:3,stem:"True or False? In the book's Control phase list, the response plan is developed **before** the monitoring plan.",options:["True","False"],answer:1,hint:"You must know what you watch before you decide how to react.",steps:[{title:"Recall",body:"Book p. 578: … Develop/Implement Documentation Plan → **Develop/Implement Monitoring Plan** → Develop/Implement Response Plan → Align Systems and Structures …"},{title:"Decide",body:"Monitoring comes first; the response plan reacts to what monitoring shows."}],final:"False → answer **B**",whyWrong:["Incorrect — the book lists the monitoring plan before the response plan; responses depend on what is monitored.",""],bookRef:"Book p. 578"},{id:"sv-5-1298",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"Why does the book call the **FMEA** a great tool to use for the monitoring plan?",options:["It calculates the control limits for each chart in the monitoring plan","It proves statistically that the vital few X's cause the defect","It replaces the need for control charts on the critical inputs","It shows the whole process and how everyone can contribute to a defect-free output, and RPNs can be reassessed as the process changes"],answer:3,hint:"Two benefits on p. 570: visibility of the whole process, and a way to stay current.",steps:[{title:"Key idea",body:"Book p. 570: the FMEA lets the process manager and staff **see the entire process** and how everyone contributes to a defect-free product, and keeps the document current by **reassessing RPNs** as the process changes."},{title:"Eliminate",body:"Limits come from SPC; statistical proof comes from hypothesis tests; the FMEA works alongside charts, not instead of them."}],final:"Whole-process view plus reassessed RPNs → answer **D**",whyWrong:["Incorrect — control limits come from the process data on the SPC chart, not from the FMEA.","Incorrect — FMEA ratings are team judgements; statistical proof comes from Analyze hypothesis tests.","Incorrect — the FMEA is listed alongside SPC charts in the monitoring plan, not as a replacement.",""],bookRef:"Book p. 570"},{id:"sv-5-1299",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"Which statement about ranking the **control methods** written into a control plan is CORRECT?",options:["SPC run by trained staff who are empowered to stop the process ranks above SPC run by staff who are not empowered","100% inspection ranks above a prevention poka-yoke because every unit is checked","An SOP alone ranks above SPC because it is cheaper to maintain","A detection poka-yoke ranks above a prevention poka-yoke because it finds more errors"],answer:0,hint:"Strength ladder: prevent > flag > empowered SPC > non-empowered SPC/inspection > SOP.",steps:[{title:"Key idea",body:"Book p. 522: Type 1 prevention > Type 2 flag (detection) > SPC with trained, **empowered** staff > SPC without empowerment and Type 3 inspection > SOP alone."},{title:"Apply",body:"Empowerment to stop for special-cause investigation is what lifts SPC up the ladder."}],final:"Empowered SPC outranks non-empowered SPC → answer **A**",whyWrong:["","Incorrect — inspection is Type 3 containment, well below prevention.","Incorrect — an SOP alone is the weakest control and not sustainable.","Incorrect — prevention (Type 1) removes the error condition and ranks above detection (Type 2)."],bookRef:"Book p. 522"},{id:"sv-5-1300",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"According to the book's Control phase checklist, who must all agree that the project is complete?",options:["The operators, the customer and the auditor","The MBB, the HR manager and the supplier","The Champion, the Belt and Finance","The process owner, the IT team and the trainer"],answer:2,hint:"Three roles: the sponsor, the leader and the money.",steps:[{title:"Key idea",body:"Book p. 578, General Questions: 'Do the **Champion, the Belt and Finance** all agree this project is complete?'"},{title:"Apply",body:"This links the control plan to verified financial impact before the Belt goes to the next project."}],final:"Champion, Belt and Finance agree → answer **C**",whyWrong:["Incorrect — operators and customers matter, but the book's completion question names Champion, Belt and Finance.","Incorrect — HR and suppliers may help build the plan, but they do not sign the project as complete.","","Incorrect — the process owner receives the plan; the completion agreement is Champion, Belt and Finance."],bookRef:"Book p. 578"},{id:"sv-5-1301",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which is a purpose of the **monitoring plan** given in the book?",options:["To assure that gains are achieved and sustained","To decide which solution to implement","To estimate the cost of poor quality","To verify the root cause with a hypothesis test"],answer:0,hint:"Book p. 568: two purposes — one about the gains, one about the future.",steps:[{title:"Key idea",body:"Book p. 568: the monitoring plan **assures gains are achieved and sustained** and provides insight for future improvement activities."},{title:"Eliminate",body:"Choosing solutions is 5.3.1; COPQ is Define; root-cause tests are Analyze."}],final:"Monitoring assures the gains are sustained → answer **A**",whyWrong:["","Incorrect — selecting a solution is done with the Improvement Selection Matrix before the plan.","Incorrect — COPQ is estimated in Define to justify the project.","Incorrect — verifying root causes with hypothesis tests belongs to Analyze."],bookRef:"Book p. 568"},{id:"sv-5-1302",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A corporate customer's supplier audit asks: *'How do you make sure the improved provisioning process keeps meeting our requirements?'* Which document BEST answers this request?",options:["The Improvement Selection Matrix","The X-Y matrix","The baseline capability study","The control plan"],answer:3,hint:"Book p. 563: control plans are becoming more of a customer requirement.",steps:[{title:"Key idea",body:"Book p. 563: '**Control Plans are becoming more of a customer requirement**' — the plan shows how the process is monitored and controlled."},{title:"Eliminate",body:"The selection matrix ranks solutions, the X-Y matrix prioritises inputs, and the baseline study describes the old process."}],final:"The customer is asking for the control plan → answer **D**",whyWrong:["Incorrect — the selection matrix shows how solutions were chosen, not how the process is kept in control.","Incorrect — the X-Y matrix prioritises inputs in Measure; it holds no ongoing controls.","Incorrect — a baseline study describes performance before improvement.",""],bookRef:"Book p. 563"},{id:"sv-5-1303",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"What does the book state is the objective of the Control phase and its control plan?",options:["To find the root causes of the defect","To sustain the gains initially found in the Define, Measure, Analyze and Improve phases","To measure the baseline performance of the process","To generate as many solution ideas as possible"],answer:1,hint:"'Remember: The objective is to…'",steps:[{title:"Key idea",body:"Book p. 556: 'Remember: The objective is to **sustain the gains** initially found in the D, M, A, I Phases.'"},{title:"Eliminate",body:"Root causes = Analyze, baseline = Measure, idea generation = Improve."}],final:"Sustain the gains → answer **B**",whyWrong:["Incorrect — root causes are found and verified in Analyze.","","Incorrect — baseline performance is established in Measure.","Incorrect — generating solution ideas is an Improve activity."],bookRef:"Book p. 556"},{id:"sv-5-1304",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`An operator policy was trialled for six weeks. Minitab descriptive statistics of fill weight (g):

\`\`\`
Descriptive Statistics: Fill Weight by Policy
Policy                          N    Mean    StDev
Respond to chart signals only  180   500.2   1.21
Adjust after every off-centre  180   500.1   1.68
\`\`\`

Which conclusion is CORRECT for the monitoring plan?`,options:["Adjusting after every reading improved the process, because the mean moved closer to 500 g","Adjusting after every off-centre reading increased variation, so the plan should require a response only to chart signals","Both policies are equal, because the means are almost the same","The control limits should be narrowed to match the adjust-every-time policy"],answer:1,hint:"Book p. 544: operators who adjust on every point produce worse variation.",steps:[{title:"Read",body:"Means are almost equal (500.2 vs 500.1), but StDev is 1.21 g with signals-only versus 1.68 g with constant adjustment."},{title:"Rule",body:"Book p. 544: variability increases if operators adjust on every point; ONLY respond to out-of-control signals."}],final:"Tampering raised the StDev → respond to signals only → answer **B**",whyWrong:["Incorrect — the mean barely changed while the spread grew; that is worse, not better.","","Incorrect — similar means hide the larger StDev under constant adjustment.","Incorrect — limits reflect the process; tampering widens, not narrows, real variation."],bookRef:"Book p. 544"},{id:"sv-5-1305",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The book's documentation plan outline has columns for the document, items necessary, immediate responsibility, update/modification responsibility and [?] responsibility.`,options:["approval","budget","review","training"],answer:2,hint:"Someone must check documents for currency and accuracy.",steps:[{title:"Recall",body:"Book p. 568: the outline columns are Document, Items Necessary, Immediate Responsibility, Update/Modification Responsibility and **Review** Responsibility."},{title:"Link",body:"Review responsibility matches p. 567: the plan must say who reviews documents for currency and accuracy."}],final:"Review → answer **C**",whyWrong:["Incorrect — approval is not a column of the book's documentation plan outline.","Incorrect — budget is not part of the documentation plan outline.","","Incorrect — trainers appear in the training plan outline, not the documentation outline."],bookRef:"Book pp. 567–568"},{id:"sv-5-1306",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:2,stem:"The control plan is implemented and handed to the process owner. The Belt is about to start a new project, but **Finance has not yet confirmed the savings**. What is the BEST next action?",options:["Start the new project and leave the savings unconfirmed","Recalculate the baseline from the Measure phase","Rewrite the control plan as a new charter","Verify the financial impact with Finance before going to the next project"],answer:3,hint:"Book p. 578 roadmap: align systems → verify financial impact → go to next project.",steps:[{title:"Key idea",body:"Book p. 578: the Control sequence ends **Verify Financial Impact → Go to Next Project**; untracked benefits are a roadblock (p. 577)."},{title:"Apply",body:"Confirm the savings with Finance first."}],final:"Verify financial impact first → answer **D**",whyWrong:["Incorrect — 'financial benefits are not tracked' is a listed roadblock.","Incorrect — the baseline is already established; the open item is the verified impact.","Incorrect — a charter starts a project; the control plan sustains this one.",""],bookRef:"Book pp. 577–578"},{id:"sv-5-1307",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`The control plan monitors a critical input (X) and the output (Y) of a billing process:

\`\`\`
Test Results for I Chart of Tariff Load Delay (min)   [X]
TEST 1. One point more than 3.00 standard deviations from center line.
Test Failed at points:  41

Test Results for P Chart of Billing Errors            [Y]
* No test failures *
\`\`\`

Which conclusion is CORRECT?`,options:["Respond to the signal on the X now, before it produces billing errors","Take no action, because the output Y shows no test failures","Stop monitoring the X, because only the Y matters to the customer","Recalculate the X chart limits to include point 41"],answer:0,hint:"You control the output by controlling its inputs.",steps:[{title:"Read",body:"The X chart fails Test 1 at point 41; the Y chart has no failures yet."},{title:"Interpret",body:"Book p. 579 lists a control plan for outputs AND for inputs; an X signal is an early warning, and response triggers usually monitor the highest-risk X's (p. 571)."}],final:"Act on the X signal now → answer **A**",whyWrong:["","Incorrect — waiting for the Y to signal means defects will already have reached customers.","Incorrect — monitoring the critical X is what prevents defects in the Y.","Incorrect — limits are not reset to absorb an unexplained special cause."],bookRef:"Book pp. 571, 579"},{id:"sv-5-1308",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which statement about an **implementation plan** is CORRECT?",options:["A back-of-the-envelope note is usually enough","It is written only after the control plan has been handed off","It should include timelines, critical milestones, project review dates and specific actions for success","It is the same document as the response plan"],answer:2,hint:"Book p. 562 margin note on planning the selected solutions.",steps:[{title:"Key idea",body:"Book p. 562: a plan means more than a back-of-the-envelope solution and should include **timelines, critical milestones, project review dates and specific actions** noted for success."},{title:"Eliminate",body:"Implementation comes before hand-off, and the response plan is a control plan element."}],final:"Timelines, milestones, reviews and actions → answer **C**",whyWrong:["Incorrect — the book says a plan means more than the proverbial back-of-the-envelope solution.","Incorrect — solutions are implemented before the control plan is handed to the process owner.","","Incorrect — the response plan says what to do on a signal; it is not the implementation plan."],bookRef:"Book p. 562"},{id:"sv-5-1309",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:2,stem:"All of the following are components of an **implementation plan** given in the book EXCEPT:",options:["A work breakdown structure","A risk management plan","A Gage R&R study of the output measure","An influence strategy for priorities and resourcing"],answer:2,hint:"Book p. 562: WBS, influence strategy, risk plan, audit of completion and risks.",steps:[{title:"Key idea",body:"Book p. 562 components: work breakdown structure, influence strategy, risk management plan, audit results for completion and risks."},{title:"Find the outsider",body:"Gage R&R is an MSA tool from Measure."}],final:"Gage R&R is MSA, not an implementation-plan component → answer **C**",whyWrong:["Incorrect — the WBS IS a listed component.","Incorrect — the risk management plan IS a listed component.","","Incorrect — the influence strategy IS a listed component."],bookRef:"Book p. 562"},{id:"sv-5-1310",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Why should each row of a control plan state **where the results are recorded** (chart, log or dashboard)?",options:["So that the control limits can be recalculated every week","So that adherence to the monitoring plan and the responses taken can be checked later","So that the specification limits can be removed from the row","So that the process owner no longer needs to be named"],answer:1,hint:"A control that leaves no record cannot be audited.",steps:[{title:"Key idea",body:"A row names the record so that monitoring and actions can be checked; the book asks for actions taken to be recorded (p. 569) and the plan to serve as a reference if results are not sustained (p. 562)."},{title:"Eliminate",body:"Recording does not change limits, specs or ownership."}],final:"Records make adherence and actions auditable → answer **B**",whyWrong:["Incorrect — limits change only on signals that performance has changed, not because results are recorded.","","Incorrect — the specification stays in the row as the customer requirement.","Incorrect — every row still needs a named owner."],bookRef:"Book pp. 562, 569"},{id:"sv-5-1311",phase:5,topic:"5.3.2",qtype:"output",difficulty:2,stem:`At hand-off the Belt reviews the documentation plan outline:

\`\`\`
Documentation Plan – Refund Process
Document            Immediate resp.   Update/Modify resp.   Review resp.
Process map v3      Belt              Process analyst       Ops manager
SOP-RF-02           Belt              Process analyst       (blank)
FMEA rev 4          Belt              Quality lead          (blank)
Training manual     Belt              Training dept         Training dept
\`\`\`

Which conclusion is CORRECT?`,options:["The process map has no one responsible for updates","The Belt should be named as reviewer for every document after hand-off","The plan is complete because every document has an immediate owner","Nobody is named to review SOP-RF-02 and the FMEA for currency and accuracy"],answer:3,hint:"Every document needs someone to update it and someone to review it.",steps:[{title:"Read",body:"Review responsibility is blank for SOP-RF-02 and FMEA rev 4; all other cells are filled."},{title:"Rule",body:"Book p. 567: the plan must outline who updates documents and who reviews them for currency and accuracy."}],final:"Review owners missing for the SOP and FMEA → answer **D**",whyWrong:["Incorrect — the process map's update responsibility is the process analyst.","Incorrect — the Belt's duty is at hand-off; ongoing review goes to named roles in the organisation.","Incorrect — immediate ownership alone is not enough; ongoing review must also be assigned.",""],bookRef:"Book pp. 567–568"},{id:"sv-5-1312",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:1,stem:"Which tool is NOT listed by the book as part of the **monitoring plan**?",options:["Design of experiments","SPC control charts","FMEA","Visual management"],answer:0,hint:"Book pp. 569–570: SPC, FMEA, checklists/matrices, visual management.",steps:[{title:"Key idea",body:"Book pp. 569–570: the monitoring plan uses SPC charts, the FMEA, check lists/matrices and visual management."},{title:"Find the outsider",body:"DOE is an Improve tool used to find optimal settings, not to monitor."}],final:"DOE is an Improve tool → answer **A**",whyWrong:["","Incorrect — SPC charts ARE part of the monitoring plan.","Incorrect — the book calls the FMEA a great tool for the monitoring plan.","Incorrect — visual management IS part of the monitoring plan."],bookRef:"Book pp. 569–570"},{id:"sv-5-1313",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"In a contact centre, a **horn sounds** when more than 20 calls are waiting, and supervisors move agents from back-office work to the phones. In the control plan, what is the horn an example of?",options:["A Type 1 prevention poka-yoke","Aligning systems and structures","Visual management in the monitoring plan","The documentation plan"],answer:2,hint:"Alerts or signals that trigger action can be audible.",steps:[{title:"Key idea",body:"Book p. 570: visual management = alerts or signals to trigger action, and they '**can be audible also**'."},{title:"Eliminate",body:"The horn does not stop the error condition (not Type 1); it is not a goal or a document."}],final:"Audible alert = visual management → answer **C**",whyWrong:["Incorrect — a Type 1 control removes the error condition; the horn only signals that action is needed.","Incorrect — aligning systems changes goals, policies and incentives.","","Incorrect — the documentation plan records and maintains documents."],bookRef:"Book p. 570"},{id:"sv-5-1314",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Besides assuring that the gains are achieved and sustained, what else does the book say a **monitoring plan** provides?",options:["Insight for future process improvement activities","The financial approval for the project","The list of potential X's for the next Analyze phase","A replacement for the training plan"],answer:0,hint:"Book p. 568 gives the monitoring plan two purposes.",steps:[{title:"Key idea",body:"Book p. 568: the monitoring plan assures gains are achieved and sustained **and provides insight for future process improvement activities**."},{title:"Eliminate",body:"Approval comes from Finance and the Champion; listing X's is Analyze; training is its own element."}],final:"Insight for future improvement → answer **A**",whyWrong:["","Incorrect — financial agreement comes from the Champion, Belt and Finance, not from the monitoring plan.","Incorrect — listing potential X's is Analyze work with the X-Y matrix and FMEA.","Incorrect — the training plan is a separate control plan element."],bookRef:"Book p. 568"},{id:"sv-5-1315",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"Which statement about **implementing solutions** before the control plan is completed is CORRECT?",options:["Only the cheapest solution needs to appear in the control plan","An implementation plan needs no risk management plan","Solutions are implemented without deadlines so the team can stay flexible","All solutions must be part of the control plan document"],answer:3,hint:"Book p. 562, last line of 'Implementing Solutions'.",steps:[{title:"Key idea",body:"Book p. 562: implementation plans organise tasks and resources, set realistic deadlines and include a WBS, influence strategy, **risk management plan** and audit — and '**All solutions must be part of Control Plan Document.**'"},{title:"Eliminate",body:"Every solution, not only the cheapest, must be controlled."}],final:"Every solution goes into the control plan → answer **D**",whyWrong:["Incorrect — the book says ALL solutions must be part of the control plan document.","Incorrect — a risk management plan is a listed component of the implementation plan.","Incorrect — the book asks for realistic time frames and deadlines.",""],bookRef:"Book p. 562"},{id:"sv-5-1316",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`Knowledge-test results for the new identity-check script:

\`\`\`
Knowledge Test Results – ID Check Script (agents passing)
When tested                    Agents   Passed   % Passed
After training (week 1)          120      118      98.3
Scheduled check (month 3)        120      114      95.0
Random audit (month 4)            60       43      71.7
\`\`\`

Which conclusion is CORRECT?`,options:["The script is well embedded because the scheduled check passed 95%","Unannounced checks show much lower use of the script, so refresher training and follow-up are needed","Random audits should be dropped because they give lower results","The training plan worked, so no more knowledge tests are needed"],answer:1,hint:"Why does the book list random intervals as well as scheduled ones?",steps:[{title:"Read",body:"98.3% after training and 95.0% at the scheduled check, but 71.7% at the random audit."},{title:"Interpret",body:"Book p. 569: sample after training, at regular intervals and at **random intervals** (auditing). The random audit exposes the gap, which should trigger refresher training (p. 565)."}],final:"Random audit reveals a gap → refresher training → answer **B**",whyWrong:["Incorrect — announced checks can overstate compliance; the random audit shows otherwise.","","Incorrect — random audits are listed by the book precisely because they reveal real practice.","Incorrect — knowledge tests are ongoing; 71.7% shows the need to continue them."],bookRef:"Book pp. 565, 569"},{id:"sv-5-1317",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"The Belt designs the sampling for a warehouse monitoring plan without asking the shift supervisors, whose staff must take the samples. The schedule clashes with the peak loading hour and samples are skipped. Which book guidance was missed?",options:["Stakeholders must be consulted when the monitoring plan is developed","Control limits must be recalculated every shift","The monitoring plan must be written by Finance","Sampling must be stopped once the process is stable"],answer:0,hint:"Book p. 568: development of a monitoring plan.",steps:[{title:"Key idea",body:"Book p. 568: the Belt develops the monitoring plan, team members help, and **stakeholders must be consulted**."},{title:"Apply",body:"Consulting the supervisors would have placed sampling outside the peak hour."}],final:"Consult stakeholders → answer **A**",whyWrong:["","Incorrect — limits change only on signals; this does not fix skipped samples.","Incorrect — Finance tracks results; it does not develop the monitoring plan.","Incorrect — monitoring continues to sustain the gains; stability does not end sampling."],bookRef:"Book p. 568"},{id:"sv-5-1318",phase:5,topic:"5.3.2",qtype:"statements",difficulty:2,stem:`Which statements describe the Belt's documentation responsibilities **at implementation**, according to the book?

1. Ensure all documents are current at hand-off.
2. Ensure there is a process to modify documentation as the process changes.
3. Personally update every SOP for as long as the process runs.
4. Obtain the external customer's approval of each SOP.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Book p. 567: three Belt duties at hand-off — current, modify process, review process.",steps:[{title:"Check each",body:"1 and 2 are listed (with ensuring a review process). 3 confuses hand-off duty with ongoing ownership. 4 is not in the book."},{title:"Match",body:"The true pair is 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — includes 3; ongoing updates go to named people in the organisation, not the Belt.","Incorrect — 3 and 4 are both outside the book's hand-off duties.","Incorrect — includes 4; customer approval of SOPs is not a listed responsibility."],bookRef:"Book p. 567"},{id:"sv-5-1319",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"What does a **response plan** outline, according to the book?",options:["The schedule for training new employees on the process","The list of documents that must be kept current","The ranking of potential solutions by impact, cost and time","The process to follow when there is a defect or an out-of-control condition from monitoring"],answer:3,hint:"Book p. 571, first line of 'Response Plan'.",steps:[{title:"Key idea",body:"Book p. 571: response plans **outline the process(es) to follow when there is a defect or out of control** from monitoring."},{title:"Eliminate",body:"Training schedule = training plan; documents = documentation plan; ranking solutions = selection matrix."}],final:"Response plan = what to do on a defect or OOC signal → answer **D**",whyWrong:["Incorrect — the schedule of training belongs to the training plan.","Incorrect — keeping documents current is the documentation plan.","Incorrect — ranking solutions is the Improvement Selection Matrix.",""],bookRef:"Book p. 571"},{id:"sv-5-1320",phase:5,topic:"5.3.3",qtype:"statements",difficulty:2,stem:`Which statements describe **triggers** for a response plan listed in the book?

1. A point that lies above the centre line but inside the control limits.
2. A request from Finance for a monthly cost report.
3. Non-random behaviour within the control limits.
4. A check-sheet failure.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Book p. 571: OOC point, non-random pattern within limits, defect-causing condition present, check-sheet failure, automation failure.",steps:[{title:"Check each",body:"3 and 4 are on the book's list. 1 is ordinary common-cause scatter. 2 is a reporting request, not a failure mode."},{title:"Match",body:"The true pair is 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — 1 and 2 are not triggers: one is common-cause scatter, the other a report request.","Incorrect — includes 2; a finance report request is not a response trigger.","","Incorrect — includes 1; a point above the centre line inside the limits is not a signal."],bookRef:"Book pp. 544, 571"},{id:"sv-5-1321",phase:5,topic:"5.3.3",qtype:"scenario",difficulty:2,stem:"Each time the dispute-rate chart signals, the billing lead records *'signal — fixed'* in the log. When the team later investigates repeat signals, they cannot tell which bill cycle, tariff version or product mix was involved. Which response-plan component is weak?",options:["The triggers for a response","The responsibilities for responding","Detailed information on the conditions surrounding the failure mode","The recommended response for the failure mode"],answer:2,hint:"The log shows that something was done, but not the circumstances.",steps:[{title:"Key idea",body:"Book p. 571: a response plan includes **detailed information on the conditions surrounding the failure mode**."},{title:"Apply",body:"Without bill cycle, tariff version and product mix, repeat causes cannot be traced."}],final:"Condition details are missing → answer **C**",whyWrong:["Incorrect — the triggers work: the chart signals and the lead reacts.","Incorrect — responsibility is clear; the billing lead acts.","","Incorrect — a fix is applied; what is missing is the record of circumstances."],bookRef:"Book pp. 571–572"},{id:"sv-5-1322",phase:5,topic:"5.3.3",qtype:"output",difficulty:2,stem:`The monitoring step for a fault-repair process produces:

\`\`\`
Test Results for I Chart of Daily Repair Backlog
TEST 3. 6 points in a row all increasing or all decreasing.
Test Failed at points:  33

* No points beyond the control limits *
\`\`\`

The response plan lists 'non-random behaviour within the control limits' as a trigger. What should happen?`,options:["Take no action, because no point is beyond the control limits","Activate the response plan, because a trend inside the limits is a trigger","Wait until a point falls beyond the UCL before responding","Recalculate the control limits to include the trend"],answer:1,hint:"Book p. 571: triggers include non-random behaviour within the limits.",steps:[{title:"Read",body:"Test 3 (6 points in a row increasing or decreasing) failed at point 33; no point is beyond the limits."},{title:"Rule",body:"Book p. 571: **non-random behaviour within control limits** is a response trigger."}],final:"Trend inside limits is a trigger → respond → answer **B**",whyWrong:["Incorrect — the book lists non-random patterns inside the limits as a trigger.","","Incorrect — waiting for a Test 1 point lets the drift continue.","Incorrect — resetting limits around an unexplained trend hides the special cause."],bookRef:"Book p. 571"},{id:"sv-5-1323",phase:5,topic:"5.3.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Response-plan triggers include an out-of-control point, non-random behaviour within the limits, a condition proven to produce defects, an automation failure and a [?] failure.`,options:["budget","check-sheet","customer","training"],answer:1,hint:"Book p. 571: five triggers.",steps:[{title:"Recall",body:"Book p. 571 triggers: OOC point; non-random behaviour within limits; condition/variable proven to produce defects present; **check sheet** failure; automation failure."},{title:"Eliminate",body:"Budget, customer and training failures are not on the list."}],final:"Check-sheet → answer **B**",whyWrong:["Incorrect — budget problems are not a response-plan trigger.","","Incorrect — 'customer failure' is not one of the book's five triggers.","Incorrect — training gaps are handled by the training plan; they are not a listed trigger."],bookRef:"Book p. 571"},{id:"sv-5-1324",phase:5,topic:"5.3.3",qtype:"concept",difficulty:1,stem:"Which question does the **triggers** component of a response plan answer?",options:["Who will be trained, and by when?","Where is the control plan filed?","How much did the project save?","What are the failure modes to check for?"],answer:3,hint:"Book p. 571: 'The triggers for a response ~ …'",steps:[{title:"Key idea",body:"Book p. 571: triggers — **what are the failure modes to check for?** — usually the highest-risk X's in the process."},{title:"Eliminate",body:"Training, filing and savings belong to other parts of Control."}],final:"Triggers = which failure modes to check for → answer **D**",whyWrong:["Incorrect — who is trained and when is the training plan.","Incorrect — where the plan is filed is shared at sign-off.","Incorrect — savings are verified with Finance.",""],bookRef:"Book p. 571"},{id:"sv-5-1325",phase:5,topic:"5.3.3",qtype:"concept",difficulty:2,stem:"Each failure mode in a response plan has its own **recommended response**. Which statement about this component is CORRECT?",options:["It is left to the person on shift to decide at the time","It is the same single action for every failure mode","It states the agreed action for each failure mode, decided before the failure occurs","It is written only after the root cause of a failure is known"],answer:2,hint:"A plan decides the action in advance.",steps:[{title:"Key idea",body:"Book p. 571: a response plan contains **the recommended response for the failure mode**, alongside triggers, responsibilities, documentation and conditions."},{title:"Apply",body:"It is agreed in advance and specific to each failure mode, so the reaction is fast and consistent."}],final:"Agreed, failure-mode-specific action in advance → answer **C**",whyWrong:["Incorrect — leaving it to the shift gives inconsistent responses; that is what the plan prevents.","Incorrect — the book gives a recommended response for EACH failure mode.","","Incorrect — the response is planned in advance; root-cause analysis follows a failure."],bookRef:"Book p. 571"}];export{e as items};
